#!/usr/bin/env Rscript

#' R script for DE analysis - part of PerSeqPIPE Nextflow workflow 
#' @author Karolina Trachtova
#' @description R script that generates various matrices of counts (raw,
#' edgeR TNM, deseq2 count, VST counts) as well as performs DE analysis
#' using provided design file
#' INPUTS:
#'   - input_dir:            [file]    Input directory with counts generated by GENOME_QUANTIFICATION module, must contain columns: sequence, expression and optionally columns like pirna, trna, MINT_plate etc.) 
#'   - design_file:          [file]    TXT tab- or comma-separated file with min 2 or max 3 columns (sample, condition, ?batch?)
#'   - generate_counts_only: [boolean] Should only normalized counts be generated (no DE analysis)? 

# Load required libraries
library(edgeR)
library(DESeq2)
library(dplyr)

timestamp <- format(Sys.time(), "%Y%m%d_%H%M%S")

##### Functions ###############################################################
rownames_to_column <- function(res) {
  # Convert to data frame
  res_df <- as.data.frame(res)
  
  # Add gene names as a proper column
  res_df$gene <- rownames(res_df)
  
  # Reorder columns to have gene first
  res_df <- res_df[, c("gene", setdiff(names(res_df), "gene"))]
  
  return(res_df)
}

# Function to create matrix of raw counts and matrix of normalized counts
# that will be added to the final DE table; samples will be renamed
# to contain in its name both condition and whether it is raw/norm count column
create_raw_norm_counts <- function(dds) {
  
  # Extract raw and normalized counts
  raw_counts <- counts(dds, normalized = FALSE) %>%
    as.data.frame() %>%
    tibble::rownames_to_column("gene")
  
  norm_counts <- counts(dds, normalized = TRUE)
  vst_counts <- assay(DESeq2::varianceStabilizingTransformation(dds))

  # Check if batch column is in colData and remove batch effect
  if ("batch" %in% colnames(colData(dds))) {
    batch <- colData(dds)$batch
    condition <- colData(dds)$condition
    norm_counts <- limma::removeBatchEffect(norm_counts, batch = batch, design = model.matrix(~ condition))
    vst_counts <- limma:removeBatchEffect(vst_counts, batch = batch, design = model.matrix(~ condition))
  }
  
  norm_counts <- as.data.frame(norm_counts) %>%
    tibble::rownames_to_column("gene")

  vst_counts <- as.data.frame(vst_counts) %>%
    tibble::rownames_to_column("gene")
  
  # Add condition info to sample names
  sample_conditions <- colData(dds)$condition
  names(sample_conditions) <- colnames(dds)
  
  rename_with_condition <- function(count_df, count_type) {
    old_names <- colnames(count_df)[-1]
    new_names <- paste0(old_names, "_", count_type, "_", sample_conditions[old_names])
    colnames(count_df)[-1] <- new_names
    return(count_df)
  }
  
  raw_counts <- rename_with_condition(raw_counts, "raw")
  norm_counts <- rename_with_condition(norm_counts, "norm")
  vst_counts <- rename_with_condition(vst_counts, "vst")
  
  merged_counts <- raw_counts %>%
    dplyr::left_join(norm_counts, by = "gene") %>%
    dplyr::left_join(vst_counts, by = "gene")
  
  return(merged_counts)
}

##### Parse input parameters ##################################################

# Get command line arguments
args <- commandArgs(trailingOnly = TRUE)

# Initialize parameters
#expression_threshold <- 20
#sample_threshold <- 6

# Test 1
#input_dir <- "/Users/kaja/Public/nextflow_results/docker_trilink_GSE262424_DE/rna_quantification/genome/counts"
#design_file <- NULL
#generate_counts_only <- TRUE

# Test 2
#input_dir <- "/Users/kaja/Public/nextflow_results/docker_trilink_GSE262424_test/rna_quantification/genome/counts"
#design_file <- "/Users/kaja/Public/nextflow/test_data/trilink_GSE262424/design_MM_PCL_EMD.txt"
#generate_counts_only <- FALSE
#setwd("/Users/kaja/Public/nextflow_results/docker_trilink_GSE262424_test/de_analysis2")

# Parse arguments
i <- 1
while (i <= length(args)) {
  if (args[i] == "--input_dir") {
    input_dir <- args[i + 1]
    i <- i + 1
  } else if (args[i] == "--design_file") {
    design_file <- args[i + 1]
    i <- i + 1
  } else if (args[i] == "--sncrna_expression_threshold") {
    thresh_parts <- strsplit(args[i + 1], ",")[[1]]
    if (length(thresh_parts) != 2) {
      stop("Error: --expression_sample_thresholds requires two comma-separated values, e.g., 10,3")
    }
    sncrna_exp <- as.numeric(thresh_parts[1])
    sncrna_sample <- as.numeric(thresh_parts[2])
    i <- i + 1
  }
  i <- i + 1
}

# Check for required input_dir
if (is.null(input_dir)) {
  stop("Error: You must provide --input_dir argument.")
}
# Validate input_dir
if (!dir.exists(input_dir)) {
  stop("Error: The input directory does not exist: ", input_dir)
}

cat("Input Directory:", input_dir, "\n")

# Handle generate-counts-only flag
if (is.null(design_file)) {
  message("No design file provided. Only normalized counts will be output.")
} else {
  if (!file.exists(design_file)) {
    stop("Error: Provided design file does not exist: ", design_file)
  }
  
  # Try to guess separator by inspecting the file
  first_line <- readLines(design_file, n = 1)
  
  if (grepl(",", first_line)) {
    sep_used <- ","
  } else if (grepl("\t", first_line)) {
    sep_used <- "\t"
  } else {
    stop("Error: Could not detect separator: neither comma nor tab found.")
  }
  
  design <- read.table(design_file, sep = sep_used, header = T)
  
  # Check column names
  valid_cols <- c("sample", "condition", "batch")
  actual_cols <- colnames(design)
  
  if (length(actual_cols) < 2 || length(actual_cols) > 3) {
    stop("Error: Design file must have min 2 and max 3 columns.")
  }
  
  if (!all(c("sample", "condition") %in% actual_cols)) {
    stop("Error: Design file must contain 'sample' and 'condition' columns.")
  }
  
  if (!all(actual_cols %in% valid_cols)) {
    stop("Error: Design file contains invalid columns. Allowed: sample, condition, batch.")
  }
  
  # Clean design matrix -> samples must be rownames, columns must be factors
  rownames(design) <- design$sample
  design$sample <- NULL
  design$condition <- factor(design$condition)
  
  # Check if the design file has a third column named 'batch'
  if ("batch" %in% colnames(design)) {
    design$batch <- factor(design$batch)
  }
  
  cat("Design File:", design_file, "\n")
  cat("Design file loaded successfully.\n")
}

##### Read input counts ########################################################

# List all files in the input directory
input_files <- list.files(input_dir, full.names = TRUE, pattern = "short_rna_counts\\.tsv$")
print(input_files)

# Initialize a list to store the data frames
df_list <- list()

# Loop through each file
for (file in input_files) {
  cat("Processing file:", file, "\n")
  
  # Read the file, expecting at least two columns (sequence, expression) and possible annotations
  data <- tryCatch({
    read.table(file, header = TRUE, sep = "\t", stringsAsFactors = FALSE)
  }, error = function(e) {
    stop("Error: Failed to read the file: ", file)
  })
  
  # Ensure the file has at least two columns (sequence, expression)
  if (ncol(data) < 2) {
    stop("Error: The file ", file, " does not have at least 2 columns.")
  }
  
  # Extract the first two columns (sequence and expression)
  expression_data <- data[, c("sequence", "expression")]

  # Annotate expression data with the file name as the column name for expression
  colnames(expression_data) <- c("sequence", gsub(".genome.*", "", basename(file)))

  # Save the expression data to the list
  df_list[[basename(file)]] <- expression_data
  
  # Store annotations (columns other than sequence and expression)
  annotation_data <- data[, !(names(data) %in% c("sequence", "expression"))]
  annotation_data$sequence <- data$sequence  # Add sequence back to the annotations
  
  # Store annotations in a separate list
  if (!exists("annotation_list")) {
    annotation_list <- list()
  }
  
  annotation_list[[basename(file)]] <- annotation_data
}

# Merge all expression data frames based on the 'sequence' column
merged_data <- df_list[[1]]
for (i in 2:length(df_list)) {
  merged_data <- merge(merged_data, df_list[[i]], by = "sequence", all = TRUE)
}

# Replace NAs in expression columns with 0 for missing values
merged_data[is.na(merged_data)] <- 0

# Now merge the annotation data
# We will merge the annotations based on the sequence column (with a suffix for uniqueness)
final_annotation <- annotation_list[[1]]
for (i in 2:length(annotation_list)) {
  combined_table <- rbind(final_annotation, annotation_list[[i]])
  final_annotation <- unique(combined_table)
  #final_annotation <- merge(final_annotation, annotation_list[[i]], by = "sequence", all = TRUE)
}

# Check which samples are in design VS counts, filter out sample missing in the design
if (!is.null(design_file)) {
  message("Sample present in raw counts but not in the design file that will be filtered out:")
  mcol <- colnames(merged_data)[colnames(merged_data) != "sequence"]
  drow <- rownames(design)
  print(mcol[!(mcol %in% drow)])
  merged_data <- merged_data[, colnames(merged_data) %in% rownames(design) | colnames(merged_data) == "sequence"]
}

# Merge expression data with annotations
final_data <- merge(merged_data, final_annotation, by = "sequence", all.x = TRUE)

# Write raw counts
write.table(merged_data, file = "sncrna_raw_counts.tsv", sep = "\t", row.names = TRUE, quote = FALSE)

# Write raw counts with annotation
write.table(final_data, file = "sncrna_raw_counts_annotated.tsv", sep = "\t", row.names = TRUE, quote = FALSE)

# Save cleaned counts and design into R data object
analysis_data_cleaned <- list(
  merged_data = if (exists("merged_data")) merged_data else NULL,
  final_data = if (exists("final_data")) final_data else NULL,
  design_df = if (exists("design")) design else NULL
)

# Save the list to a file
saveRDS(analysis_data_cleaned, file = "analysis_data_cleaned.rds")

# Make sequences as rownames -> required for edger, deseq2 to work properly
rownames(merged_data) <- merged_data$sequence
merged_data$sequence <- NULL

##### Counts normalization #####################################################


# If user does not provide design file, do dummy normalization and at least
# provide this type of counts
if (is.null(design_file)) {

  # -------------------------------
  # 1. EdgeR TMM Normalization
  # -------------------------------

  # Create a DGEList object for edgeR normalization
  dge <- DGEList(counts = merged_data)
  dge <- calcNormFactors(dge, method = "TMM")  # TMM normalization
  tmm_counts <- cpm(dge, normalized.lib.sizes = TRUE)
  tmm_counts_df <- rownames_to_column(tmm_counts)
  write.table(
    tmm_counts_df,
    file = paste0("normalized_tmm_counts_sncrna.tsv"),
    sep = "\t", quote = FALSE, row.names = FALSE
  )

  # -------------------------------
  # 2. DESeq2 Normalization (Size Factors)
  # -------------------------------

  # Create a DESeqDataSet for DESeq2
  dds <- DESeqDataSetFromMatrix(countData = merged_data, colData = DataFrame(condition = rep("Condition", ncol(merged_data))), design = ~1)
  dds <- DESeq(dds)
  deseq2_counts <- counts(dds, normalized = TRUE)
  deseq2_counts_df <- rownames_to_column(deseq2_counts)
  write.table(
    deseq2_counts_df,
    file = paste0("normalized_deseq2_counts_sncrna.tsv"),
    sep = "\t", quote = FALSE, row.names = FALSE
  )

  # -------------------------------
  # 3. DESeq2 VST (Variance-Stabilizing Transformation)
  # -------------------------------

  vst_matrix <- assay(DESeq2::varianceStabilizingTransformation(dds))
  vst_matrix_df <- rownames_to_column(vst_matrix)
  write.table(
    vst_matrix_df,
    file = paste0("normalized_vst_counts_sncrna.tsv"),
    sep = "\t", quote = FALSE, row.names = FALSE
  )

  # -------------------------------

  cat("Normalization completed. The results are saved in:\n")
  cat("1. normalized_tmm_counts_sncrna.tsv\n")
  cat("2. normalized_deseq2_counts_sncrna.tsv\n")
  cat("3. normalized_vst_counts_sncrna.tsv\n")

}
##### Run DE analysis ##########################################################

# Check design file is specified and --generate-counts-only is FALSE
if (!is.null(design_file)) {

  message("#######################################")
  message("Starting DE analysis for sRNA counts...")
  
  # Check if the design file has a third column named 'batch'
  use_batch <- "batch" %in% colnames(design)
  
  # Create a DESeqDataSet object from the count matrix and design file
  counts_matrix <- merged_data  # Get the expression matrix without annotations

  # Ensure the rownames in the design file match the column names of the counts matrix
  if (!all(rownames(design) %in% colnames(counts_matrix))) {
    stop("Error: The sample names in the design file do not match the columns in the counts matrix!")
  }
  
  # Ensure order of samples is the same in bot hdesign and matrix of counts
  counts_matrix <- counts_matrix[, rownames(design)]
  if (!all(colnames(counts_matrix) == rownames(design))) {
    stop("Error: Order of samples in your matrix of counts and design file is not the same!")
  }

  # Create DESeq2 object
  # If batch column exists, include it in the design formula
  if (use_batch) {
    message("Including batch effect in the model\n")
    dds <- DESeqDataSetFromMatrix(countData = counts_matrix, colData = design, design = ~ batch + condition)
  } else {
    message("No batch effect supplied, proceeding without batch correction.\n")
    dds <- DESeqDataSetFromMatrix(countData = counts_matrix, colData = design, design = ~ condition)
  }
  
  # Filter out sequences not achieving expression threshold in given number of samples
  if (!is.null(sncrna_exp) && !is.null(sncrna_sample)) {
    message(sprintf("Filtering based on expression ≥ %d in at least %d samples",
                    sncrna_exp, sncrna_sample))
    dds <- dds[rowSums(counts(dds) >= sncrna_exp) >= sncrna_sample, ]
  }
  
  # Perform DE analysis
  dds <- DESeq(dds)
  
  # Create the file name using the timestamp
  dds_filename <- paste0("dds_sncrna.rds")
  # Save the dds object as an RDS file
  saveRDS(dds, file = dds_filename)
  
  # Check how many conditions supplied, if more than 2 do LRT and save results
  if (length(levels(dds$condition)) >= 3){
    if (use_batch) {
      dds_lrt <- DESeq(dds, test = "LRT", reduced = ~ batch)
    } else {
      dds_lrt <- DESeq(dds, test = "LRT", reduced = ~ 1)
    }
    res_lrt <- results(dds_lrt) %>%
      as.data.frame() %>%
      tibble::rownames_to_column("gene") %>%
      dplyr::select(gene,
                    baseMean = baseMean,
                    stat_lrt = stat,
                    pvalue_lrt = pvalue,
                    padj_lrt = padj)
    res_lrt <- res_lrt %>%
      arrange(padj_lrt)
    # Save the dds object
    dds_lrt_filename <- paste0("dds_lrt_sncrna.rds")
    saveRDS(dds_lrt, file = dds_lrt_filename)
    # Save the table
    # output_file <- paste0("DE_analysis_srna_LRT_results.tsv")
    # write.table(res_lrt, file = output_file, sep = "\t", quote = FALSE, row.names = FALSE)
  }
    
  # Get all levels of condition
  cond_levels <- levels(dds$condition)
  comparisons <- combn(cond_levels, 2, simplify = FALSE)  # Generate pairwise comparisons
  
  # Initialize list to store each comparison
  pairwise_results <- list()
  
  for (comp in comparisons) {
    cond_a <- comp[1]
    cond_b <- comp[2]
    comp_name <- paste0(cond_a, "_vs_", cond_b)
    message("Performing comparison: ", cond_a, " vs ", cond_b)
    
    # Get DE results
    res <- results(dds, contrast = c("condition", cond_a, cond_b))
  
    # Convert to clean data frame
    res_df <- as.data.frame(res) %>%
      tibble::rownames_to_column("gene") %>%
      dplyr::select(gene,
                    !!paste0("logFC_", comp_name) := log2FoldChange,
                    !!paste0("stat_", comp_name) := stat,
                    !!paste0("pval_", comp_name) := pvalue,
                    !!paste0("padj_", comp_name) := padj)
    
    pairwise_results[[comp_name]] <- res_df
    
    # Save result
    #output_file <- paste0("DE_analysis_srna_", comp_name, "_results.tsv")
    #write.table(res_df, file = output_file, sep = "\t", quote = FALSE, row.names = FALSE)
  }
  
  # In case we have >= 3 conditions, we need to merge all comparisons
  if (length(levels(dds$condition)) >= 3) {
    # do LRT and get res_lrt
    # merge with pairwise_results as you have now
    final_results <- res_lrt
    for (comp_name in names(pairwise_results)) {
      final_results <- left_join(final_results, pairwise_results[[comp_name]], by = "gene")
    }
  } else {
    # only 2 conditions: final_results is just that single pairwise result
    final_results <- pairwise_results[[1]]
  }
  
  # Merge with annotation
  final_results_annot <- merge(final_annotation, final_results, by.x = "sequence", by.y= "gene", all.x = FALSE, all.y = TRUE)
  final_results_annot <- final_results_annot %>%
    arrange(padj_lrt)
  
  # Save result
  output_file <- paste0("DE_analysis_sncrna_", paste(levels(dds$condition), collapse = "_"), "_results.tsv")
  write.table(final_results_annot, file = output_file, sep = "\t", quote = FALSE, row.names = FALSE)
  
  # Obtain raw and normalized counts - order of rows==sequences('gene' column)
  # will be identical to the DE table so its easy to merge
  counts_table <- create_raw_norm_counts(dds)
  output_file <- paste0("DE_analysis_sncrna_", paste(levels(dds$condition), collapse = "_"), "_counts.tsv")
  write.table(counts_table, file = output_file, sep = "\t", quote = FALSE, row.names = FALSE)
  
  
  message("All pairwise DE comparisons for sRNA completed.\n")
  
} else {
  cat("Skipping differential expression analysis. Either no design file or --generate-counts-only flag is set.\n")
}

# Save full environment and history
save.image(paste0("de_analysis_sncrna.rds"))
#savehistory(file = paste0("de_analysis_srna_history_", timestamp, ".txt"))
